/**
 * Bibliothèque d'icônes Mélampus — v2.0
 *
 * Deux familles :
 *  — Portraits animaux   bi-color (ink + brand), illustratifs, toutes tailles
 *  — Icônes navigation   mono fill (currentColor), 24 × 24 interne
 *
 * Mapping couleurs fournis → charte :
 *  #66bb6a  →  #0E5B45  (brand)
 *  #212121  →  #0F1A16  (ink)
 *
 * Espèces couvertes :
 *  equine   → HorsePortrait     (SVG fourni)
 *  bovine   → CowPortrait       (généré)
 *  ovine    → SheepPortrait     (généré)
 *  caprine  → GoatPortrait      (SVG fourni)
 *  porcine  → PigPortrait       (généré)
 *  canine   → DogPortrait       (généré)
 *  feline   → CatPortrait       (généré)
 *  avian    → HenPortrait       (SVG fourni)
 *  other    → RabbitPortrait    (SVG fourni)
 */

import type { ReactNode, ReactElement } from 'react'
import type { Species } from '@melampus/api-types'

const INK   = '#0F1A16'
const BRAND = '#0E5B45'

// ─── Type taille ─────────────────────────────────────────────────────────────

export type PortraitSize = 'sm' | 'md' | 'lg'

function portraitPx(size: PortraitSize): number {
  return size === 'lg' ? 64 : size === 'sm' ? 28 : 36
}

// ─── Wrapper commun des portraits ─────────────────────────────────────────────

function PortraitBox({
  size,
  children,
}: {
  size: PortraitSize
  children: ReactNode
}) {
  const cls =
    size === 'lg'
      ? 'w-20 h-20 rounded-md'
      : size === 'sm'
        ? 'w-9 h-9 rounded-sm'
        : 'w-11 h-11 rounded-sm'
  return (
    <div
      className={`${cls} border border-line bg-paper inline-flex items-center justify-center flex-shrink-0`}
    >
      {children}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// PORTRAITS ANIMAUX (SVGs fournis, couleurs charte)
// ─────────────────────────────────────────────────────────────────────────────

