// ─────────────────────────────────────────────────────────────────────────────
// DISPATCHER — AnimalPortrait
// ─────────────────────────────────────────────────────────────────────────────

const PORTRAIT_MAP: Record<Species, (size: PortraitSize) => ReactElement> = {
  equine:  size => <HorsePortrait  size={size} />,
  bovine:  size => <CowPortrait    size={size} />,
  ovine:   size => <SheepPortrait  size={size} />,
  caprine: size => <GoatPortrait   size={size} />,
  porcine: size => <PigPortrait    size={size} />,
  canine:  size => <DogPortrait    size={size} />,
  feline:  size => <CatPortrait    size={size} />,
  avian:   size => <HenPortrait    size={size} />,
  other:   size => <RabbitPortrait size={size} />,
}

/** Composant principal — à utiliser dans les cartes et fiches animal */
export function AnimalPortrait({
  species,
  size = 'md',
}: {
  species: Species
  size?: PortraitSize
}) {
  const render = PORTRAIT_MAP[species] ?? (s => <GenericPortrait size={s} />)
  return render(size)
}

